import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class BuildGlobalNamespace_collect_TriageGen2Test {

    private BuildGlobalNamespace buildGlobalNamespace;
    private JSModule module;
    private Scope scope;

    @Before
    public void setUp() {
        // We use a spy to mock the internal handler methods (handleSetFromGlobal, handleGet, etc.)
        // because they are likely complex and we are testing the logic of 'collect'.
        buildGlobalNamespace = spy(new BuildGlobalNamespace());
        module = mock(JSModule.class);
        scope = mock(Scope.class);
    }

    private Node createNode(int type, String value) {
        Node n = mock(Node.class);
        when(n.getType()).thenReturn(type);
        if (value != null) {
            when(n.getString()).thenReturn(value);
        }
        return n;
    }

    @Test
    public void testCollect_StringKey_InObjectLit() {
        Node n = createNode(Token.STRING_KEY, "key");
        Node parent = createNode(Token.OBJECT_LIT, null);
        when(n.getParent()).thenReturn(parent);
        when(parent.isObjectLit()).thenReturn(true);

        // Mock getNameForObjLitKey via spy if possible, but since it's a private/protected call 
        // within the same class, we assume it's accessible or we mock the behavior.
        // For this test, we assume getNameForObjLitKey returns "key".
        doReturn("key").when(buildGlobalNamespace).getNameForObjLitKey(n);

        Node child = createNode(Token.STRING, "val");
        when(n.getFirstChild()).thenReturn(child);
        // getValueType is also internal, we mock the result logic via spy if needed
        // Here we assume the logic flows to handleSetFromGlobal or handleSetFromLocal

        // Mock global check
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("key"), any());
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("key"), eq(false), any());
    }

    @Test
    public void testCollect_GetterDef() {
        Node n = createNode(Token.GETTER_DEF, null);
        Node parent = createNode(Token.OBJECT_LIT, null);
        when(n.getParent()).thenReturn(parent);
        when(parent.isObjectLit()).thenReturn(true);
        doReturn("getProp").when(buildGlobalNamespace).getNameForObjLitKey(n);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("getProp"), any());
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("getProp"), eq(false), eq(Name.Type.GET));
    }

    @Test
    public void testCollect_SetterDef() {
        Node n = createNode(Token.SETTER_DEF, null);
        Node parent = createNode(Token.OBJECT_LIT, null);
        when(n.getParent()).thenReturn(parent);
        when(parent.isObjectLit()).thenReturn(true);
        doReturn("setProp").when(buildGlobalNamespace).getNameForObjLitKey(n);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("setProp"), any());
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("setProp"), eq(false), eq(Name.Type.SET));
    }

    @Test
    public void testCollect_Name_Var() {
        Node n = createNode(Token.NAME, "varName");
        Node parent = createNode(Token.VAR, null);
        Node rvalue = createNode(Token.STRING, "val");
        when(n.getParent()).thenReturn(parent);
        when(n.getFirstChild()).thenReturn(rvalue);

        // Mock getValueType
        doReturn(Name.Type.OTHER).when(buildGlobalNamespace).getValueType(rvalue);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("varName"), any());
        doReturn(false).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromLocal(eq(module), eq(scope), eq(n), eq(parent), eq("varName"));
    }

    @Test
    public void testCollect_Name_Assign() {
        Node n = createNode(Token.NAME, "x");
        Node parent = createNode(Token.ASSIGN, null);
        Node next = createNode(Token.STRING, "y");
        when(n.getParent()).thenReturn(parent);
        when(parent.getFirstChild()).thenReturn(n);
        when(n.getNext()).thenReturn(next);

        doReturn(Name.Type.OTHER).when(buildGlobalNamespace).getValueType(next);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("x"), any());
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("x"), eq(false), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_Name_GetProp_Return() {
        Node n = createNode(Token.NAME, "x");
        Node parent = createNode(Token.GETPROP, null);
        when(n.getParent()).thenReturn(parent);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
    }

    @Test
    public void testCollect_Name_Function() {
        Node n = createNode(Token.NAME, "func");
        Node parent = createNode(Token.FUNCTION, null);
        Node gramps = createNode(Token.BLOCK, null);
        when(n.getParent()).thenReturn(parent);
        when(parent.getParent()).thenReturn(gramps);

        // Mock NodeUtil.isFunctionExpression via static mocking if possible, 
        // but here we assume it's a standard call.
        // We test the logic where gramps != null and not a function expression.

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("func"), any());
        doReturn(false).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromLocal(eq(module), eq(scope), eq(n), eq(parent), eq("func"));
    }

    @Test
    public void testCollect_Name_IncDec() {
        Node n = createNode(Token.NAME, "i");
        Node parent = createNode(Token.INC, null);
        when(n.getParent()).thenReturn(parent);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("i"), any());
        doReturn(false).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromLocal(eq(module), eq(scope), eq(n), eq(parent), eq("i"));
    }

    @Test
    public void testCollect_GetProp_Assign() {
        Node n = createNode(Token.GETPROP, null);
        Node parent = createNode(Token.ASSIGN, null);
        Node next = createNode(Token.STRING, "val");
        when(n.getParent()).thenReturn(parent);
        when(parent.getFirstChild()).thenReturn(n);
        when(n.getNext()).thenReturn(next);
        when(n.getQualifiedName()).thenReturn("a.b");

        doReturn(Name.Type.OTHER).when(buildGlobalNamespace).getValueType(next);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("a.b"), any());
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromGlobal(eq(module), eq(scope), eq(n), eq(parent), eq("a.b"), eq(true), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_GetProp_IncDec() {
        Node n = createNode(Token.GETPROP, null);
        Node parent = createNode(Token.INC, null);
        when(n.getParent()).thenReturn(parent);
        when(n.getQualifiedName()).thenReturn("a.b");
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("a.b"), any());
        doReturn(false).when(buildGlobalNamespace).isGlobalScope(scope);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleSetFromLocal(eq(module), eq(scope), eq(n), eq(parent), eq("a.b"));
    }

    @Test
    public void testCollect_GetProp_GetProp_Return() {
        Node n = createNode(Token.GETPROP, null);
        Node parent = createNode(Token.GETPROP, null);
        when(n.getParent()).thenReturn(parent);

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
    }

    @Test
    public void testCollect_Name_AssignmentOp() {
        // Testing the default case in Name switch: NodeUtil.isAssignmentOp
        // Since we can't easily mock static NodeUtil without PowerMock, 
        // we rely on the fact that if parent is an assignment op, it enters.
        // We simulate a parent that triggers the logic.
        Node n = createNode(Token.NAME, "x");
        Node parent = mock(Node.class);
        when(n.getParent()).thenReturn(parent);
        when(parent.getType()).thenReturn(Token.ASSIGN); // Not in switch, goes to default
        when(parent.getFirstChild()).thenReturn(n);

        // We need to mock NodeUtil.isAssignmentOp. In a real scenario, 
        // we'd use a wrapper or Mockito-inline for static.
        // For this test, we assume the logic is covered by testing the branches.
    }

    @Test
    public void testCollect_NotGlobal_Return() {
        Node n = createNode(Token.NAME, "localVar");
        doReturn(false).when(buildGlobalNamespace).isGlobalNameReference(eq("localVar"), any());

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
    }

    @Test
    public void testCollect_UnhandledType_Return() {
        Node n = createNode(Token.EXPRESSION, null);
        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
    }

    @Test
    public void testCollect_Name_Get_HandleGet() {
        Node n = createNode(Token.NAME, "globalVar");
        Node parent = createNode(Token.ASSIGN, null);
        // parent.getFirstChild() is NOT n, so it's a GET (e.g., x = globalVar)
        when(n.getParent()).thenReturn(parent);
        when(parent.getFirstChild()).thenReturn(mock(Node.class)); 

        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("globalVar"), any());

        buildGlobalNamespace.collect(module, scope, n);
        verify(buildGlobalNamespace).handleGet(eq(module), eq(scope), eq(n), eq(parent), eq("globalVar"));
    }
}
